<?php
require __DIR__.'/../config/database.php';require_login();$error='';$bookingId=filter_input(INPUT_GET,'booking_id',FILTER_VALIDATE_INT)?:filter_input(INPUT_POST,'booking_id',FILTER_VALIDATE_INT);
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$rating=filter_input(INPUT_POST,'rating',FILTER_VALIDATE_INT);$comment=trim((string)($_POST['comment']??''));if(!$rating||$rating<1||$rating>5||strlen($comment)>2000)$error='Điểm đánh giá hoặc nội dung không hợp lệ.';else{$st=$pdo->prepare("SELECT b.court_id FROM bookings b WHERE b.id=? AND b.user_id=? AND b.status='completed' AND b.booking_date<=CURDATE()");$st->execute([$bookingId,current_user()['id']]);$b=$st->fetch();if(!$b)$error='Chỉ đánh giá lượt đặt đã hoàn thành của bạn.';else{try{$st=$pdo->prepare('INSERT INTO reviews(user_id,court_id,booking_id,rating,comment) VALUES(?,?,?,?,?)');$st->execute([current_user()['id'],$b['court_id'],$bookingId,$rating,$comment?:null]);flash('Cảm ơn bạn đã đánh giá.');redirect('/user/bookings.php');}catch(PDOException){$error='Đơn này đã được đánh giá.';}}}}
$st=$pdo->prepare("SELECT b.id,c.name FROM bookings b JOIN courts c ON c.id=b.court_id LEFT JOIN reviews r ON r.booking_id=b.id WHERE b.user_id=? AND b.status='completed' AND b.booking_date<=CURDATE() AND r.id IS NULL ORDER BY b.booking_date DESC");$st->execute([current_user()['id']]);$eligible=$st->fetchAll();$pageTitle='Đánh giá sân';require __DIR__.'/../includes/header.php';?><div class="card card-body form-card"><h1 class="h3">Đánh giá sân</h1><?php if($error): ?><div class="alert alert-danger"><?= e($error) ?></div><?php endif; ?><?php if(!$eligible): ?><p>Bạn chưa có lượt đặt hoàn thành nào đủ điều kiện đánh giá.</p><?php else: ?><form method="post"><?= csrf_field() ?><label class="form-label">Lượt đặt</label><select class="form-select mb-3" name="booking_id"><?php foreach($eligible as $b): ?><option value="<?= (int)$b['id'] ?>" <?= (int)$bookingId===(int)$b['id']?'selected':'' ?>>#<?= (int)$b['id'] ?> · <?= e($b['name']) ?></option><?php endforeach; ?></select><label class="form-label">Số sao</label><select class="form-select mb-3" name="rating"><option value="5">5 - Rất tốt</option><option value="4">4 - Tốt</option><option value="3">3 - Bình thường</option><option value="2">2 - Chưa tốt</option><option value="1">1 - Kém</option></select><label class="form-label">Nhận xét</label><textarea class="form-control mb-3" name="comment" maxlength="2000" rows="4"></textarea><button class="btn btn-success">Gửi đánh giá</button></form><?php endif; ?></div><?php require __DIR__.'/../includes/footer.php'; ?>
